from typing import Optional

from seat import Seat

@dataclass(frozen=True)
class Hold:
    id: int
    seat_id: int
    patron: str
    state: str = field(default="placed")

@dataclass(frozen=True)
class HoldBook:
    """Hold book for a library reading room."""

    books: dict[int, Hold] = field(default_factory=dict)

    def place_hold(self, hold: Hold) -> None:
        """Place a hold on a seat."""
        self.books[hold.id] = hold

    def claim_hold(self, hold: Hold) -> None:
        """Claim a hold on a seat."""
        self.books[hold.id] = hold

    def cancel_hold(self, hold: Hold) -> None:
        """Cancel a hold on a seat."""
        if hold.id in self.books:
            del self.books[hold.id]

    def list_holds(self) -> list[Hold]:
        """List all holds."""
        return list(self.books.values())

    def validate_patron(self, name: str) -> str:
        """Validate a patron's name."""
        return name if name else "Empty name"
